import re
from pathlib import Path

ЗАПИС = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})")
ВИНЯТОК = re.compile(r"^([^\s:]+):(?:\s|$)")


def зчитати_записи(шлях):
    записи = []
    поточний = None
    with open(шлях, encoding="utf-8-sig") as f:
        for рядок in f:
            рядок = рядок.rstrip("\r\n")
            м = ЗАПИС.match(рядок)
            if м:
                поточний = {"час": м.group(1), "продовження": []}
                записи.append(поточний)
            elif рядок[:1] in (" ", "\t") and поточний is not None:
                поточний["продовження"].append(рядок.strip())
    return записи


def main():
    шлях = Path("дані") / "журнал.txt"
    часи_за_типом = {}
    for запис in зчитати_записи(шлях):
        типи = []
        for рядок in запис["продовження"]:
            м = ВИНЯТОК.match(рядок)
            if м:
                типи.append(м.group(1))
        if not типи:
            continue
        тип = типи[-1]
        часи_за_типом.setdefault(тип, []).append(запис["час"])

    впорядковано = sorted(часи_за_типом.items(), key=lambda kv: (-len(kv[1]), kv[0]))
    for тип, часи in впорядковано:
        print(f"{тип}: {len(часи)} ({min(часи)}, {max(часи)})")


if __name__ == "__main__":
    main()

